"""The estimators MA201 built. Read-only: this module is about using them."""


def mean(values):
    """The arithmetic mean."""
    if not values:
        raise ValueError("no values to average")
    return sum(values) / len(values)


def sample_variance(values):
    """The unbiased sample variance, with the n - 1 divisor."""
    if len(values) < 2:
        raise ValueError("a variance needs at least two observations")
    m = mean(values)
    return sum((x - m) ** 2 for x in values) / (len(values) - 1)


def percentile(values, q):
    """The q quantile, by linear interpolation between order statistics."""
    if not values:
        raise ValueError("no values to take a percentile of")
    if not 0.0 <= q <= 1.0:
        raise ValueError("q must lie in [0, 1]")
    xs = sorted(values)
    if len(xs) == 1:
        return float(xs[0])
    position = q * (len(xs) - 1)
    low = int(position)
    high = min(low + 1, len(xs) - 1)
    weight = position - low
    return xs[low] * (1 - weight) + xs[high] * weight


def median(values):
    """The 0.5 quantile."""
    return percentile(values, 0.5)

